#!/usr/bin/env bash
set -Eeuo pipefail

# Frozen V3 four-cell fresh-data runner. The manifest and init directory are
# generated by capacity_study_v3_collection.py and are treated as immutable.

SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
CORE_DIR="$(cd "${SCRIPT_DIR}/../.." && pwd)"
REPO_DIR="$(cd "${CORE_DIR}/.." && pwd)"
MODELS_DIR="${CORE_DIR}/scripts/models"
PYTHON_BIN="${PYTHON_BIN:-python}"
COLLECTION_SET="${COLLECTION_SET:?Set COLLECTION_SET to general_test or interaction_challenge}"
PROTOCOL_ROOT="${PROTOCOL_ROOT:-${CORE_DIR}/results/capacity_history_v3/protocol}"
RESULTS_DIR="${RESULTS_DIR:-${CORE_DIR}/results/capacity_history_v3/${COLLECTION_SET}}"
MANIFEST="${MANIFEST:-${PROTOCOL_ROOT}/${COLLECTION_SET}_manifest.json}"
INIT_DIR="${INIT_DIR:-${PROTOCOL_ROOT}/inits/${COLLECTION_SET}}"
TUNING_CONFIG="${TUNING_CONFIG:-${SCRIPT_DIR}/scenarios/tuning_configs/give_way_reduced_clear_path_release_v12_current_best.json}"
PREDICTION_MODEL_WEIGHTS="${PREDICTION_MODEL_WEIGHTS:-l5kit_multipath_10_carla_finetuned_head_best}"
PREDICTION_MODEL_ANCHORS="${PREDICTION_MODEL_ANCHORS:-l5kit_clusters_16.npy}"
LOG_STRIDE="${LOG_STRIDE:-4}"
LOG_HORIZON="${LOG_HORIZON:-10}"
SKIP_COMPLETED_SUBRUNS="${SKIP_COMPLETED_SUBRUNS:-1}"
ENABLE_CAMERA_VIZ="${ENABLE_CAMERA_VIZ:-0}"
ADAPTIVE_CONFIG='{"variant_name":"floor_weak","approach_preclearance_floor":1.66,"critical_preclearance_floor":1.72,"near_preclearance_floor":1.78}'
REACTIVE_CONFIG_JSON="${REACTIVE_CONFIG_JSON:-}"

case "${COLLECTION_SET}" in
  general_test|interaction_challenge) ;;
  *) echo "Invalid COLLECTION_SET=${COLLECTION_SET}" >&2; exit 2 ;;
esac
: "${CARLA_ROOT:?Set CARLA_ROOT to the CARLA 0.9.14 directory}"
for required in \
  "${CARLA_ROOT}/PythonAPI/carla/agents/navigation/global_route_planner.py" \
  "${MANIFEST}" "${INIT_DIR}" "${TUNING_CONFIG}"; do
  test -e "${required}" || { echo "Missing V3 collection input: ${required}" >&2; exit 2; }
done

export PYTHONPATH="${CARLA_ROOT}/PythonAPI/carla:${CARLA_ROOT}/PythonAPI/carla/agents:${MODELS_DIR}:${PYTHONPATH:-}"
mkdir -p "${RESULTS_DIR}"

# Validate the source-controlled plan and require the init files to match the
# exact group list before CARLA is allowed to run.
"${PYTHON_BIN}" - "${MANIFEST}" "${INIT_DIR}" "${COLLECTION_SET}" <<'PY'
import json, sys
from pathlib import Path
from capacity_study_v3_collection import validate_collection_manifest
manifest_path, init_dir, expected_set = Path(sys.argv[1]), Path(sys.argv[2]), sys.argv[3]
manifest = json.loads(manifest_path.read_text())
report = validate_collection_manifest(manifest)
if report["collection_set"] != expected_set:
    raise SystemExit("collection-set/manifest mismatch")
expected = {f"ego_init_{value:02d}.json" for value in manifest["ego_init_ids"]}
observed = {path.name for path in init_dir.glob("ego_init_*.json")}
if observed != expected:
    raise SystemExit(f"init matrix mismatch: missing={sorted(expected-observed)}, extra={sorted(observed-expected)}")
PY

GIT_COMMIT="${PREDICTION_GIT_COMMIT:-$(git -C "${REPO_DIR}" rev-parse HEAD)}"
camera_args=(--disable_camera_viz)
[[ "${ENABLE_CAMERA_VIZ}" == "1" ]] && camera_args=(--enable_camera_viz)
resume_args=()
[[ "${SKIP_COMPLETED_SUBRUNS}" == "1" ]] && resume_args=(--skip_completed_subruns)
reactive_args=()
[[ -n "${REACTIVE_CONFIG_JSON}" ]] && reactive_args=(--reactive_config_json "${REACTIVE_CONFIG_JSON}")

run_cell() {
  local cell_id="$1" target_style="$2" policy="$3" risk_profile="$4" ego_policy_label="$5"
  shift 5
  local cell_dir="${RESULTS_DIR}/${cell_id}"
  mkdir -p "${cell_dir}"
  "${PYTHON_BIN}" "${SCRIPT_DIR}/run_all_scenarios.py" \
    --scenario_glob "scenario_uk_give_way.json" \
    --init_glob "${INIT_DIR}/ego_init_*.json" \
    --results_dir "${cell_dir}" \
    --policies "${policy}" \
    --risk_profile "${risk_profile}" \
    --tuning_config "${TUNING_CONFIG}" \
    --target_style "${target_style}" \
    --prediction_model_weights "${PREDICTION_MODEL_WEIGHTS}" \
    --prediction_model_anchors "${PREDICTION_MODEL_ANCHORS}" \
    --enable_prediction_logging \
    --prediction_logging_stride "${LOG_STRIDE}" \
    --prediction_logging_horizon "${LOG_HORIZON}" \
    --prediction_logging_save_raster \
    --prediction_dataset_version "give_way_capacity_history_prediction_v3.0" \
    --prediction_protocol_id "town05_capacity_history_${COLLECTION_SET}_v3" \
    --prediction_feature_schema_id "give_way_interaction_sequence_v2" \
    --prediction_cell_id "${cell_id}" \
    --prediction_ego_policy_label "${ego_policy_label}" \
    --prediction_git_commit "${GIT_COMMIT}" \
    "${reactive_args[@]}" "${camera_args[@]}" "${resume_args[@]}" \
    --skip_postprocess "$@"
}

run_cell S0_FIXED assertive_constant_speed smpc_fixed_risk fixed_frontier_medium fixed_medium
run_cell S0_ADAPTIVE assertive_constant_speed smpc_var_risk adaptive_interaction_severity adaptive_floor_weak \
  --adaptive_risk_config_json "${ADAPTIVE_CONFIG}"
run_cell S1_FIXED defensive_reactive smpc_fixed_risk fixed_frontier_medium fixed_medium
run_cell S1_ADAPTIVE defensive_reactive smpc_var_risk adaptive_interaction_severity adaptive_floor_weak \
  --adaptive_risk_config_json "${ADAPTIVE_CONFIG}"

"${PYTHON_BIN}" "${MODELS_DIR}/capacity_study_v3_collection.py" audit \
  --manifest "${MANIFEST}" --results-dir "${RESULTS_DIR}" \
  --output "${RESULTS_DIR}/COLLECTION_AUDIT.json"
"${PYTHON_BIN}" - "${RESULTS_DIR}/COLLECTION_AUDIT.json" <<'PY'
import json, sys
report=json.load(open(sys.argv[1]))
if report.get("status") != "pass":
    raise SystemExit(f"V3 collection incomplete: {report}")
PY
"${PYTHON_BIN}" "${MODELS_DIR}/capacity_study_v3_collection.py" seal \
  --manifest "${MANIFEST}" --results-dir "${RESULTS_DIR}" \
  --output-dir "${RESULTS_DIR}/sealed"
echo "V3 ${COLLECTION_SET} collection sealed: ${RESULTS_DIR}/sealed"
